using System;
using System.Collections.Generic;
using System.Linq;
using QuietCamp.Infrastructure;
using QuietCamp.Presentation.World;
using UnityEditor;
using UnityEngine;
using UnityEngine.Rendering;

namespace QuietCamp.Editor.LevelAuthoring.WorldOps
{
    /// <summary>Preview-only surface bake. Source meshes are generated by the canonical runtime owner.</summary>
    public static class WorldOpsMeadowHeightFields
    {
        public static void Bake(LevelAuthoringDocument document,int resolution,bool adaptive=false)
        {
            ValidateRenderingShader();
            var art=document.art;
            if(art.fieldCover==null)art.fieldCover=new CampArtDefinition.FieldCoverSettings();
            if(!art.fieldCover.continuousMeadow||art.fieldCover.heightFields!=null
                ||art.atmosphere?.season=="winter")throw new InvalidOperationException("Bake requires an unbaked continuous meadow outside winter.");
            if(resolution!=256&&resolution!=512&&resolution!=1024)throw new ArgumentException("Expected 256, 512 or 1024 surface samples.");
            var root=new GameObject("WorldOps temporary canonical meadow"){hideFlags=HideFlags.HideAndDontSave};
            CampGroundDetails details=null;
            try
            {
                var patches=new List<MeadowHeightFieldPatch>();
                details=root.AddComponent<CampGroundDetails>();
                details.InspectGeneratedMeadow=(mesh,flowers)=>
                {
                    int samples=resolution;
                    if(adaptive)
                    {
                        var b=mesh.bounds;
                        float nearest=Mathf.Max(0,Mathf.Max(Mathf.Max(b.min.x,-b.max.x),Mathf.Max(b.min.z,-b.max.z)));
                        float near=Mathf.Max(document.level.width,document.level.height)*.5f+1;
                        samples=nearest<near?Mathf.Min(1024,resolution*2):nearest<22?resolution:Mathf.Max(64,resolution/4);
                    }
                    var flowerSet=new HashSet<int>(flowers);
                    var grassIndices=Enumerable.Range(0,mesh.vertexCount).Where(i=>!flowerSet.Contains(i)).ToArray();
                    var grass=MeadowHeightFieldView.CreateMesh(ReadChannels(mesh,grassIndices));
                    try
                    {
                        var patch=BakePatch(grass,samples);patch.name=mesh.name;
                        if(flowers.Count>0)patch.flowers=ReadChannels(mesh,flowers);
                        patches.Add(patch);
                    }
                    finally{UnityEngine.Object.DestroyImmediate(grass);}
                };
                details.Configure(document.level,null,art);
                if(patches.Count==0)throw new InvalidOperationException("No meadow meshes to bake.");
                art.fieldCover.heightFields=patches.ToArray();art.fieldCover.Validate();
            }
            finally{if(details!=null)details.Dispose();UnityEngine.Object.DestroyImmediate(root);}
        }
        public static MeadowRetainedMesh ReadChannels(Mesh mesh,IReadOnlyList<int> indices)
        {
            var points=mesh.vertices;var normals=mesh.normals;var colours=mesh.colors;var response=mesh.uv2;int count=indices.Count;
            var result=new MeadowRetainedMesh{vertices=new float[count*3],normals=new float[count*3],colours=new float[count*4],response=new float[count*2]};
            for(int i=0;i<count;i++)
            {
                int index=indices[i];var p=points[index];var n=normals[index];var c=colours[index];var r=response[index];
                result.vertices[i*3]=p.x;result.vertices[i*3+1]=p.y;result.vertices[i*3+2]=p.z;
                result.normals[i*3]=n.x;result.normals[i*3+1]=n.y;result.normals[i*3+2]=n.z;
                result.colours[i*4]=c.r;result.colours[i*4+1]=c.g;result.colours[i*4+2]=c.b;result.colours[i*4+3]=c.a;
                result.response[i*2]=r.x;result.response[i*2+1]=r.y;
            }
            result.Validate();return result;
        }
        public static void ValidateRenderingShader()
        {
            var shader=Shader.Find("QuietCamp/MeadowHeightField");
            if(shader==null||!shader.isSupported)throw new InvalidOperationException("Height-field rendering shader unavailable.");
            var material=new Material(shader);
            try
            {
                foreach(var shadow in new[]{"","_MAIN_LIGHT_SHADOWS","_MAIN_LIGHT_SHADOWS_CASCADE","_MAIN_LIGHT_SHADOWS_SCREEN"})
                foreach(var soft in new[]{"","_SHADOWS_SOFT_HIGH"})
                {
                    material.shaderKeywords=new[]{shadow,soft}.Where(k=>k.Length>0).ToArray();
                    for(int pass=0;pass<material.passCount;pass++)ShaderUtil.CompilePass(material,pass,true);
                }
                var errors=ShaderUtil.GetShaderMessages(shader).Where(m=>m.severity==UnityEditor.Rendering.ShaderCompilerMessageSeverity.Error).ToArray();
                if(errors.Length>0)throw new InvalidOperationException("Height-field shader compilation failed: "+errors[0].message);
            }
            finally{UnityEngine.Object.DestroyImmediate(material);}
        }
        public static MeadowHeightFieldPatch BakePatch(Mesh mesh,int resolution)
        {
            if(mesh==null)throw new ArgumentNullException(nameof(mesh));
            var shader=Shader.Find("Hidden/QuietCamp/WorldOpsMeadowBake");
            if(shader==null||!shader.isSupported)throw new InvalidOperationException("Meadow bake shader unavailable.");
            var material=new Material(shader);var bounds=mesh.bounds;
            var rect=new Vector4(bounds.min.x-.65f,bounds.min.z-.65f,bounds.size.x+1.3f,bounds.size.z+1.3f);
            var heights=new Vector4(bounds.min.y-.04f,bounds.max.y+.04f,0,0);
            material.SetVector("_BakeRect",rect);material.SetVector("_BakeHeights",heights);
            var colour=new RenderTexture(resolution,resolution,24,RenderTextureFormat.ARGB32,RenderTextureReadWrite.Linear){filterMode=FilterMode.Point};
            var normal=new RenderTexture(resolution,resolution,0,RenderTextureFormat.ARGB32,RenderTextureReadWrite.Linear){filterMode=FilterMode.Point};
            var previous=RenderTexture.active;var command=new CommandBuffer{name="WorldOps canonical meadow surface bake"};
            try
            {
                colour.Create();normal.Create();command.SetRenderTarget(new[]{new RenderTargetIdentifier(colour),new RenderTargetIdentifier(normal)},new RenderTargetIdentifier(colour));
                command.ClearRenderTarget(true,true,Color.clear,1);command.DrawMesh(mesh,Matrix4x4.identity,material,0,0);Graphics.ExecuteCommandBuffer(command);
                var images=ReadPair(colour,normal,Mathf.CeilToInt(.12f*resolution/Mathf.Min(rect.z,rect.w)));
                return new MeadowHeightFieldPatch{name=mesh.name,rect=new[]{rect.x,rect.y,rect.z,rect.w},heights=new[]{heights.x,heights.y},resolution=resolution,
                    albedoPng=images[0],normalHeightPng=images[1]};
            }
            finally
            {
                RenderTexture.active=previous;command.Release();colour.Release();normal.Release();
                UnityEngine.Object.DestroyImmediate(colour);UnityEngine.Object.DestroyImmediate(normal);UnityEngine.Object.DestroyImmediate(material);
            }
        }
        static string[] ReadPair(RenderTexture colour,RenderTexture normal,int radius)
        {
            var albedo=Read(colour);var surface=Read(normal);
            try
            {
                // Supply a nearby response in empty texels so inverse wind can find a displaced
                // blade. RGB and the normal/height validity mask remain untouched.
                var pixels=albedo.GetPixels32();var mask=surface.GetPixels32();int n=colour.width;
                var distance=new int[pixels.Length];var queue=new Queue<int>();
                for(int i=0;i<distance.Length;i++)
                {distance[i]=-1;if(mask[i].r+mask[i].g+mask[i].b>0){distance[i]=0;queue.Enqueue(i);}}
                void Visit(int from,int to)
                {
                    if(distance[to]>=0)return;distance[to]=distance[from]+1;
                    pixels[to].a=pixels[from].a;queue.Enqueue(to);
                }
                while(queue.Count>0)
                {
                    int i=queue.Dequeue();if(distance[i]>=radius)continue;int x=i%n,z=i/n;
                    if(x>0)Visit(i,i-1);if(x<n-1)Visit(i,i+1);if(z>0)Visit(i,i-n);if(z<n-1)Visit(i,i+n);
                }
                albedo.SetPixels32(pixels);albedo.Apply();
                return new[]{Convert.ToBase64String(albedo.EncodeToPNG()),Convert.ToBase64String(surface.EncodeToPNG())};
            }
            finally{UnityEngine.Object.DestroyImmediate(albedo);UnityEngine.Object.DestroyImmediate(surface);}
        }
        static Texture2D Read(RenderTexture source)
        {
            var texture=new Texture2D(source.width,source.height,TextureFormat.RGBA32,false,true);
            RenderTexture.active=source;texture.ReadPixels(new Rect(0,0,source.width,source.height),0,0);texture.Apply();return texture;
        }
    }
}
